  const triggerFocus = useCallback(async (point?: {x: number, y: number}) => {
      const now = Date.now();
      // Throttle auto-focus (when no point provided) to prevent constant seeking
      // Allow manual focus (point provided) more frequently
      const throttleTime = point ? 500 : 2500;

      if (now - lastFocusTimeRef.current < throttleTime) return; 
      lastFocusTimeRef.current = now;

      if (!streamRef.current) return;
      const videoTrack = streamRef.current.getVideoTracks()[0];
      if (!videoTrack) return;

      // Update reticle position
      if (point) {
          setReticlePosition(point);
      } else {
          setReticlePosition({x: 50, y: 50});
      }

      // Visual feedback
      setShowFocusReticle(true);
      setIsFocusing(true); // START BLUR

      // Define a cleanup/completion handler
      const finishFocus = () => {
          setShowFocusReticle(false);
          setIsFocusing(false); // END BLUR
      };

      try {
          // If we have a point, apply focus control. Otherwise, try to auto focus
          if (point) {
              await videoTrack.applyConstraints({
                  advanced: [{
                      focusMode: 'manual',
                      focusX: point.x,
                      focusY: point.y
                  }]
              });
          } else {
              await videoTrack.applyConstraints({
                  advanced: [{
                      focusMode: 'continuous',
                  }]
              });
          }
      } catch (err) {
          console.error('Focus Error: ', err);
      } finally {
          // After a minimum delay, reset the focusing state.
          setTimeout(() => finishFocus(), 300);
      }
  }, []);
